{
    public static IReadOnlyList<CharacterInfographicAsset> All { get; } = Array.AsReadOnly<CharacterInfographicAsset>(
    [
        new("raymond", "01-databasedesign", "Fra behov til databasedesign", "/images/characters/raymond/infographics/01-databasedesign.png", "/images/characters/raymond/infographics/01-databasedesign.webp", "Raymond forklarer vejen fra caféens behov over E/R-diagram og SQL-struktur til dokumentation.", 1536, 1024, "H1", [1, 4, 8], "Fra behov og E/R-diagram til tabeller og dokumentation.", ["Et databasedesign beskriver, hvilke data der skal gemmes, hvordan de hænger sammen, og hvilke regler der beskytter dem.", "E/R-diagrammet dokumenterer entiteter, nøgler og relationer, før de omsættes til tabeller.", "CREATE TABLE, ALTER TABLE og DROP TABLE opretter, ændrer og fjerner tabelstrukturen.", "CREATE DATABASE og DROP DATABASE er databaseadministration, som kræver passende rettigheder og en separat øvedatabase; kommandoerne er blokeret i SQL-H1-sandboxen."], "CREATE TABLE suppliers (\n  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  name text NOT NULL\n);\nALTER TABLE suppliers ADD COLUMN city text;\nDROP TABLE suppliers;", [new("PostgreSQL 16: tabeldefinition", "https://www.postgresql.org/docs/16/ddl-basics.html"), new("PostgreSQL 16: CREATE DATABASE", "https://www.postgresql.org/docs/16/sql-createdatabase.html"), new("SQL-H1: DDL og E/R", "https://sql.mercantec.tech/learn/ddl-01-intro")]),
        new("raymond", "02-relationer-og-noegler", "Nøgler og relationer", "/images/characters/raymond/infographics/02-relationer-og-noegler.png", "/images/characters/raymond/infographics/02-relationer-og-noegler.webp", "Raymond viser primær- og fremmednøgler samt relationerne én til én, én til mange og mange til mange.", 1536, 1024, "H1", [1, 5], "Nøgler identificerer rækker og forbinder tabeller med den rigtige kardinalitet.", ["En primærnøgle identificerer en række entydigt; en fremmednøgle henviser til en nøgle i en anden eller samme tabel.", "I en én-til-mange-relation ligger fremmednøglen på mange-siden, for eksempel orders.customer_id.", "En valgfri én-til-én-udvidelse kræver unikhed på profilens fremmednøgle, så en kunde højst kan have én profil.", "Mange-til-mange modelleres med en koblingstabel; caféens orders er en forenklet ordrelinjemodel mellem kunder og produkter.", "NOT NULL på en fremmednøgle gør henvisningen obligatorisk for barnet, men sikrer ikke, at alle forældrerækker har et barn."], "CREATE TABLE customer_profiles (\n  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  customer_id integer NOT NULL UNIQUE REFERENCES customers(id),\n  biography text\n);", [new("PostgreSQL 16: nøgler og fremmednøgler", "https://www.postgresql.org/docs/16/ddl-constraints.html"), new("SQL-H1: kardinalitet", "https://sql.mercantec.tech/learn/relations-02-cardinalitet")]),
        new("raymond", "03-constraints", "Regler, der beskytter dine data", "/images/characters/raymond/infographics/03-constraints.png", "/images/characters/raymond/infographics/03-constraints.webp", "Raymond viser NOT NULL, UNIQUE, CHECK og FOREIGN KEY med gyldige og ugyldige cafédata.", 1536, 1024, "H1", [6, 11], "Constraints kontrollerer obligatoriske værdier, unikhed, betingelser og gyldige henvisninger.", ["Constraints beskytter reglerne i selve databasen, også når data kommer fra flere forskellige programmer.", "NOT NULL afviser NULL, mens UNIQUE som udgangspunkt gør ikke-NULL-værdier unikke; PostgreSQL tillader normalt flere NULL-værdier under UNIQUE.", "CHECK kontrollerer en betingelse, men et resultat på NULL afvises ikke af CHECK alene; derfor bruges NOT NULL også, når en værdi er obligatorisk.", "En fremmednøgle sikrer, at en angivet ikke-NULL-henvisning findes i den refererede nøgle.", "Vælg sletteadfærd bevidst: automatisk CASCADE er ikke den rigtige løsning i alle datamodeller."], "CREATE TABLE cafe_orders (\n  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  customer_id integer REFERENCES customers(id),\n  order_code text NOT NULL UNIQUE,\n  quantity integer NOT NULL CHECK (quantity > 0)\n);", [new("PostgreSQL 16: constraints", "https://www.postgresql.org/docs/16/ddl-constraints.html"), new("SQL-H1: konsistens og constraints", "https://sql.mercantec.tech/learn/constraints-01-intro")]),
        new("raymond", "04-select", "Find de rigtige rækker", "/images/characters/raymond/infographics/04-select.png", "/images/characters/raymond/infographics/04-select.webp", "Raymond viser en SELECT-forespørgsel, der finder caféens kunder i Viborg og sorterer dem efter navn.", 1536, 1024, "H1", [2], "SELECT, WHERE og ORDER BY vælger kolonner, filtrerer rækker og sorterer resultatet.", ["FROM angiver datakilden, WHERE filtrerer rækkerne, og SELECT vælger de værdier, der skal vises i resultatet.", "ORDER BY angiver resultatets rækkefølge; uden ORDER BY er rækkefølgen ikke garanteret.", "I SQL-H1-caféens startdata giver eksemplet Anna Jensen, Clara Holm og Freja Olsen fra Viborg i alfabetisk rækkefølge.", "NULL er en manglende eller ukendt værdi og undersøges med IS NULL eller IS NOT NULL, ikke med = NULL.", "Funktioner kan beregne værdier i resultatet, for eksempel upper(name), uden at opdatere de gemte navne."], "SELECT name, city\nFROM customers\nWHERE city = 'Viborg'\nORDER BY name;", [new("PostgreSQL 16: SELECT", "https://www.postgresql.org/docs/16/sql-select.html"), new("SQL-H1: WHERE", "https://sql.mercantec.tech/learn/select-03-where"), new("SQL-H1: NULL", "https://sql.mercantec.tech/learn/select-10-null")]),
        new("raymond", "05-gruppering", "Fra rækker til overblik", "/images/characters/raymond/infographics/05-gruppering.png", "/images/characters/raymond/infographics/05-gruppering.webp", "Raymond forklarer GROUP BY, COUNT og forskellen på WHERE og HAVING med caféens varekategorier.", 1536, 1024, "H1", [2], "GROUP BY og aggregater opsummerer rækker; WHERE og HAVING filtrerer på hver sin side af grupperingen.", ["WHERE filtrerer de enkelte rækker, før de bliver samlet i grupper af GROUP BY.", "Aggregater som COUNT, SUM, AVG, MIN og MAX beregner værdier for hver gruppe.", "HAVING filtrerer de færdige grupper, for eksempel så kun kategorier med mindst to varer vises.", "COUNT(*) tæller rækker, mens COUNT(kolonne) tæller de rækker, hvor den valgte kolonne ikke er NULL.", "I caféens startdata er der fire drikke og to madvarer på lager; Bagværk har kun én vare på lager og bliver derfor filtreret fra af HAVING."], "SELECT category, COUNT(*) AS antal\nFROM products\nWHERE in_stock = TRUE\nGROUP BY category\nHAVING COUNT(*) >= 2\nORDER BY category;", [new("PostgreSQL 16: grupper og HAVING", "https://www.postgresql.org/docs/16/queries-table-expressions.html#QUERIES-GROUP"), new("SQL-H1: gruppering og aggregering", "https://sql.mercantec.tech/learn/select-05-group")]),
        new("raymond", "06-aendr-data", "Ændr data med omtanke", "/images/characters/raymond/infographics/06-aendr-data.png", "/images/characters/raymond/infographics/06-aendr-data.webp", "Raymond forklarer INSERT, UPDATE og DELETE samt kontrol og valg mellem COMMIT og ROLLBACK i en transaktion.", 1536, 1024, "H1", [3, 10], "Tilføj, ret og fjern rækker med tydelig kontrol af mål og resultat.", ["INSERT tilføjer rækker, UPDATE ændrer værdier i udvalgte rækker, og DELETE fjerner udvalgte rækker.", "Kontrollér betingelsen med SELECT, og undersøg resultatet af ændringen; et WHERE-udtryk kan stadig være forkert eller ramme flere rækker end forventet.", "BEGIN starter en transaktion, COMMIT afslutter den med at gemme ændringerne, og ROLLBACK afslutter den uden at bevare transaktionens ændringer.", "I eksemplet sættes prisen for produkt id 2 midlertidigt til 37, hvorefter ROLLBACK bevarer den oprindelige pris.", "Ved samtidige ændringer skal den valgte transaktionsisolering og eventuel låsning også passe til forløbet; en SELECT-kontrol alene giver ingen garanti."], "BEGIN;\nSELECT id, name, price FROM products WHERE id = 2;\nUPDATE products SET price = 37 WHERE id = 2;\nSELECT id, name, price FROM products WHERE id = 2;\nROLLBACK;", [new("PostgreSQL 16: datamanipulation", "https://www.postgresql.org/docs/16/dml.html"), new("PostgreSQL 16: transaktioner", "https://www.postgresql.org/docs/16/tutorial-transactions.html"), new("SQL-H1: transaktioner", "https://sql.mercantec.tech/learn/advanced-03-transactions")]),
        new("raymond", "07-join-og-subqueries", "JOIN og subqueries", "/images/characters/raymond/infographics/07-join-og-subqueries.png", "/images/characters/raymond/infographics/07-join-og-subqueries.webp", "Raymond sammenligner JOIN, LEFT JOIN og EXISTS med to kunder og to ordrer. Asta har to match; Bo bevares kun af LEFT JOIN.", 1536, 1024, "H1", [7], "Saml rækker med JOIN, bevar venstre side med LEFT JOIN, eller undersøg om et match findes med EXISTS.", ["De viste kunder og ordrer er forenklede café-eksempeltabeller; en JOIN kombinerer hvert par af rækker, der opfylder ON-betingelsen, her customers.id = orders.customer_id.", "Asta har to ordrer og giver derfor to resultatrækker, mens Bo uden ordrer udelades af en almindelig INNER JOIN.", "LEFT JOIN bevarer også Bo og udfylder ordre-felterne med NULL, når der ikke findes et match.", "En korreleret EXISTS-subquery returnerer en sand/falsk-værdi for hver ydre række og kan finde kunder med mindst én ordre uden at gentage kunden for hvert match."], "SELECT c.name, o.id AS order_id\nFROM customers AS c\nLEFT JOIN orders AS o ON o.customer_id = c.id\nORDER BY c.id, o.id;\n\nSELECT c.name\nFROM customers AS c\nWHERE EXISTS (\n    SELECT 1 FROM orders AS o WHERE o.customer_id = c.id\n);", [new("PostgreSQL 16 · Table expressions og JOIN", "https://www.postgresql.org/docs/16/queries-table-expressions.html"), new("PostgreSQL 16 · EXISTS og subquery expressions", "https://www.postgresql.org/docs/16/functions-subquery.html")]),
        new("raymond", "08-normalisering", "Normalisering", "/images/characters/raymond/infographics/08-normalisering.png", "/images/characters/raymond/infographics/08-normalisering.webp", "Raymond viser normalisering: et gentaget kundenavn flyttes fra orders til customers, som ordrerne forbindes med via customer_id. Under diagrammet står huskeregler for 1NF, 2NF og 3NF.", 1536, 1024, "H1", [1, 17], "Gem hvert faktum det rigtige sted, og undgå modstridende rettelser i gentagne oplysninger.", ["De viste café-eksempeltabeller er forenklede; normalisering organiserer relationer for at mindske gentagen lagring og problemer ved indsættelse, opdatering og sletning.", "1NF kræver individuelle værdier uden gentagne grupper; i 2NF skal hver ikke-nøgleattribut desuden afhænge af hele hver kandidatnøgle, ikke blot en del af en sammensat nøgle.", "Billedets 3NF-huskeregel handler om at undgå, at en ikke-nøgleattribut bestemmes gennem en anden ikke-nøgleattribut: kundenavnet hører til kunden og ikke til den enkelte ordre.", "Før-tabellen har allerede enkelte værdier og en enkel ordre-nøgle, så før/efter-eksemplet demonstrerer især forbedringen til 3NF; billederne er ikke en fuld formel definition af alle normalformer.", "Efter opdelingen kan kundenavnet ændres ét sted, mens orders.customer_id stadig peger på den relevante kunde med en fremmednøgle."], "CREATE TABLE normalized_customers (\n    id integer PRIMARY KEY,\n    name text NOT NULL\n);\nCREATE TABLE normalized_orders (\n    id integer PRIMARY KEY,\n    customer_id integer NOT NULL REFERENCES normalized_customers(id)\n);", [new("Microsoft Learn · Normalisering af databaser", "https://learn.microsoft.com/en-us/troubleshoot/microsoft-365-apps/access/database-normalization-description"), new("PostgreSQL 16 · Nøgler og fremmednøgler", "https://www.postgresql.org/docs/16/ddl-constraints.html")]),
        new("raymond", "09-views-og-rettigheder", "Views og rettigheder", "/images/characters/raymond/infographics/09-views-og-rettigheder.png", "/images/characters/raymond/infographics/09-views-og-rettigheder.webp", "Raymond viser et products-udsnit med name, price og cost_price, et menu-view med kun name og price samt SELECT-adgang til rollen cafe_reader.", 1536, 1024, "H1", [9, 10], "Gem en forespørgsel som view, og giv roller præcis den nødvendige adgang.", ["Et almindeligt PostgreSQL-view gemmer en forespørgselsdefinition og beregner resultatet ved brug; det er ikke en selvstændig kopi af tabellens data.", "De viste produkter og priser er forenklede café-eksempeltabeller, hvor menu udelader den interne cost_price-kolonne.", "GRANT SELECT på et view kan indgå i mindste privilegium, men et view er ikke automatisk en sikkerhedsgrænse: schema-adgang, øvrige grants, view-ejerskab og relevante sikkerhedsindstillinger skal planlægges og testes.", "Brug særskilte roller og kontrollér også adgang direkte til basetabellen; PostgreSQLs security_invoker- og security_barrier-valg har forskellige formål og bør ikke forveksles.", "Oprettelse af roller og tildeling af rettigheder hører til en database, du administrerer, og skal ikke forventes at virke i H1-sitets begrænsede elev-sandbox."], "CREATE VIEW menu AS\nSELECT name, price\nFROM products;\n\n-- Kræver en eksisterende rolle og ret til at tildele adgang.\nGRANT SELECT ON menu TO cafe_reader;", [new("PostgreSQL 16 · CREATE VIEW og sikkerhedsvalg", "https://www.postgresql.org/docs/16/sql-createview.html"), new("PostgreSQL 16 · GRANT", "https://www.postgresql.org/docs/16/sql-grant.html")]),
        new("raymond", "10-procedurer-og-triggere", "Procedurer og triggere", "/images/characters/raymond/infographics/10-procedurer-og-triggere.png", "/images/characters/raymond/infographics/10-procedurer-og-triggere.webp", "Raymond sammenligner en procedure startet med CALL og en trigger, der automatisk kører en triggerfunktion ved BEFORE UPDATE. Begge spor viser kontrol og mulige fejl.", 1536, 1024, "H1", [10, 12, 13], "En procedure startes med CALL; en trigger reagerer automatisk på en hændelse.", ["I PostgreSQL kaldes en stored procedure med CALL og kan bruge parametre, IF-betingelser og fejlhåndtering til administration eller databehandling.", "En trigger oprettes for en tabelhændelse og udfører en triggerfunktion, ikke en procedure; funktionen returnerer typen trigger.", "Billedets forenklede BEFORE UPDATE-rækketrigger kan undersøge NEW og returnere NEW ved godkendelse eller afbryde med RAISE EXCEPTION ved en ugyldig værdi.", "Brug helst almindelige constraints til simple integritetskrav, og vælg triggere til logik, der faktisk kræver hændelsesstyret behandling.", "Definitionerne nedenfor kræver en træningsdatabase med oprettelsesrettigheder og en products-tabel med id og price; de er ikke en garanti for, at H1-sandkassen tillader at oprette rutiner."], "CREATE OR REPLACE PROCEDURE ret_pris(p_id integer, p_price numeric)\nLANGUAGE plpgsql AS $$\nBEGIN\n    IF p_price IS NULL OR p_price <= 0 THEN\n        RAISE EXCEPTION 'Prisen skal være positiv';\n    END IF;\n    UPDATE products SET price = p_price WHERE id = p_id;\nEND;\n$$;\nCALL ret_pris(1, 35);\n\nCREATE OR REPLACE FUNCTION kontroller_pris()\nRETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n    IF NEW.price IS NULL OR NEW.price <= 0 THEN\n        RAISE EXCEPTION 'Prisen skal være positiv';\n    END IF;\n    RETURN NEW;\nEND;\n$$;\nCREATE TRIGGER products_price_check\nBEFORE UPDATE ON products\nFOR EACH ROW EXECUTE FUNCTION kontroller_pris();", [new("PostgreSQL 16 · CREATE PROCEDURE", "https://www.postgresql.org/docs/16/sql-createprocedure.html"), new("PostgreSQL 16 · Triggerfunktioner og hændelser", "https://www.postgresql.org/docs/16/trigger-definition.html"), new("PostgreSQL 16 · IF og fejlhåndtering i PL/pgSQL", "https://www.postgresql.org/docs/16/plpgsql-control-structures.html")]),
        new("raymond", "11-indeks", "Indeks", "/images/characters/raymond/infographics/11-indeks.png", "/images/characters/raymond/infographics/11-indeks.webp", "Raymond sammenligner sekventiel læsning af mange rækker med et separat indeks, der peger på relevante rækker. Billedet viser også ekstra plads og arbejde ved skrivning.", 1536, 1024, "H2", [15], "Et indeks er en ekstra adgangsvej til data med både fordele og omkostninger.", ["Et indeks kan hjælpe PostgreSQL med at finde udvalgte rækker via en separat struktur i stedet for at læse hele tabellen.", "Et indeks på orders.customer_id kan være relevant for hyppige filtre eller JOIN-betingelser på den kolonne, men forbedringen afhænger af forespørgsler og datamængde.", "Indekset fylder på lageret og skal vedligeholdes, når relevante data indsættes, opdateres eller slettes.", "Et indeks er derfor ikke altid den hurtigste løsning; for små tabeller eller forespørgsler, der læser mange rækker, kan en sekventiel scanning være et godt valg.", "Brug realistiske data, opdateret statistik og EXPLAIN til at kontrollere den valgte plan frem for at oprette et indeks på hver kolonne."], "CREATE INDEX idx_orders_customer\nON orders (customer_id);\n\nEXPLAIN SELECT * FROM orders WHERE customer_id = 1;", [new("PostgreSQL 16 · Introduktion til indekser", "https://www.postgresql.org/docs/16/indexes-intro.html"), new("PostgreSQL 16 · Undersøg brugen af indekser", "https://www.postgresql.org/docs/16/indexes-examine.html")]),
        new("raymond", "12-performance", "Mål før du optimerer", "/images/characters/raymond/infographics/12-performance.png", "/images/characters/raymond/infographics/12-performance.webp", "Raymond sammenligner EXPLAIN og EXPLAIN ANALYZE og viser en PostgreSQL-forespørgsel på caféens ordrer.", 1536, 1024, "H2", [16], "Læs planen, mål den faktiske kørsel, og sammenlign igen på realistiske data.", ["EXPLAIN viser den plan, PostgreSQL forventer at bruge, uden at køre SELECT-forespørgslen.", "EXPLAIN ANALYZE udfører forespørgslen og viser blandt andet faktisk tid og faktiske rækker. BUFFERS tilføjer oplysninger om bufferarbejdet.", "Cost er et estimat i plannerens omkostningsenheder og kan ikke læses som millisekunder.", "Sammenlign samme forespørgsel på realistiske datamængder før og efter en ændring. Cache, statistik og øvrig belastning kan påvirke målingen."], "EXPLAIN (ANALYZE, BUFFERS)\nSELECT * FROM orders\nWHERE customer_id = 1;", [new("PostgreSQL 16: EXPLAIN", "https://www.postgresql.org/docs/16/using-explain.html"), new("SQL-H1: Drift og EXPLAIN", "https://sql.mercantec.tech/learn/drift-02-backup-explain")]),
        new("raymond", "13-orm", "Fra C# til database", "/images/characters/raymond/infographics/13-orm.png", "/images/characters/raymond/infographics/13-orm.webp", "Raymond viser EF Core med to adskilte veje: Code First fra C#-model til database og reverse engineering fra database til model.", 1536, 1024, "H2", [1, 18, 19, 20], "ORM forbinder kode og database; migrations og reverse engineering løser forskellige opgaver.", ["En ORM som Entity Framework Core forbinder objekter i en domain-model med data i en database og kan generere SQL til forespørgsler.", "Med Code First beskriver du modellen i C#. En migration beskriver schemaændringer, som kan anvendes på databasen.", "Reverse engineering læser et eksisterende databaseskema og genererer entity-klasser og en DbContext. Kontroller og tilpas den genererede model.", "De to arbejdsgange er ikke en automatisk, tabsfri synkronisering. Se også SQL, relationer og constraints, når du vurderer modellen."], "var customers = await db.Customers\n    .Where(c => c.City == \"Viborg\")\n    .ToListAsync();", [new("EF Core: Migrations", "https://learn.microsoft.com/en-us/ef/core/managing-schemas/migrations/"), new("EF Core: Reverse engineering", "https://learn.microsoft.com/en-us/ef/core/managing-schemas/scaffolding/")]),
        new("raymond", "14-dokumentdatabaser", "Relationer eller dokumenter?", "/images/characters/raymond/infographics/14-dokumentdatabaser.png", "/images/characters/raymond/infographics/14-dokumentdatabaser.webp", "Raymond sammenligner cafédata som relaterede tabeller og som et dokument og peger på valg ud fra opslag og konsistens.", 1536, 1024, "H3", [21, 22], "Vælg datamodel efter de opslag, ændringer og konsistenskrav, din løsning har.", ["En relationel database organiserer data i tabeller med nøgler, relationer og constraints. JOIN kan forbinde relevante rækker ved læsning.", "En dokumentdatabase gemmer dokumenter, som kan indeholde indlejrede objekter og lister. Relaterede data kan også forbindes med referencer.", "Indlejring kan passe til data, der ofte læses samlet; mange uafhængige ændringer eller voksende lister kan gøre en anden model mere hensigtsmæssig. Fleksibelt schema kræver stadig validering og omtanke om konsistens.", "ORM er et adgangslag til en database, ikke en tredje databasetype. Sammenlign løsninger ved at måle realistiske adgangsmønstre og tydeliggøre krav til relationer og konsistens."], "{\n  \"name\": \"Anna\",\n  \"city\": \"Viborg\"\n}", [new("MongoDB: Datamodellering", "https://www.mongodb.com/docs/manual/data-modeling/best-practices/"), new("EF Core: Overblik", "https://learn.microsoft.com/en-us/ef/core/")]),
        new("raymond", "15-databasesikkerhed", "Sikker SQL begynder i appen", "/images/characters/raymond/infographics/15-databasesikkerhed.png", "/images/characters/raymond/infographics/15-databasesikkerhed.webp", "Raymond viser parameteriseret SQL, mindst mulige rettigheder, TLS og sikker opbevaring af hemmeligheder.", 1536, 1024, "H3", [14, 23], "Forebyg SQL injection med parametre, og beskyt adgangen med rettigheder, TLS og sikker opbevaring af hemmeligheder.", ["Parameteriserede forespørgsler forebygger SQL injection ved at holde SQL-struktur og værdier adskilt. Parametre kan ikke bruges som tabelnavne eller som vilkårlige SQL-fragmenter.", "I Npgsql er $1 en positionsparameter; dens værdi tilføjes separat til parameterlisten. Parametre kan repræsentere værdier, men ikke vilkårlige tabelnavne eller SQL-fragmenter.", "Giv databaserollen kun de nødvendige rettigheder. Brug TLS til forbindelsen, og opbevar credentials i et sikkert secrets- eller miljøsystem frem for i kildekoden.", "Adgangskoder skal beskyttes med salt og en egnet stærk password-hash. Kryptering af data og forbindelsen løser andre opgaver end password-hashing.", "TLS beskytter data under transport. Kryptering af lagrede data og sikker opbevaring af nøgler er særskilte valg; adgangskoder lagres som saltede, stærke hashes frem for reversibel kryptering."], "await using var cmd = dataSource.CreateCommand(\n    \"SELECT name FROM customers WHERE city = $1\");\ncmd.Parameters.Add(new() { Value = city });\nawait using var reader = await cmd.ExecuteReaderAsync();", [new("Npgsql: Parametre", "https://www.npgsql.org/doc/basic-usage.html#parameters"), new("PostgreSQL 16: Kryptering", "https://www.postgresql.org/docs/16/encryption-options.html")]),
        new("raymond", "16-databasetest", "Test databasen med forventninger", "/images/characters/raymond/infographics/16-databasetest.png", "/images/characters/raymond/infographics/16-databasetest.webp", "Raymond viser testforløbet startdata, handling og forventning samt gyldige og ugyldige databasehandlinger i en isoleret testdatabase.", 1536, 1024, "H3", [24], "Test kendte data, ugyldige tilfælde, rollback, rettigheder og samtidighed i en isoleret database.", ["Start med kendte testdata, udfør en handling, og sammenlign det faktiske resultat med en præcis forventning.", "Test både gyldige tilfælde og grænsetilfælde: NULL, dubletter, ugyldige fremmednøgler og transaktioner, der skal rulles tilbage.", "Kontroller også rettigheder, migrationer og samtidige ændringer. En afvist handling skal efterlade den forventede konsistente tilstand.", "Brug en isoleret testdatabase, og vælg samme databaseprovider som produktion, når testen skal bevise databasespecifik SQL-semantik og adfærd. En in-memory-erstatning kan ikke bevise alle disse forhold."], "BEGIN;\nINSERT INTO customers (name, city)\nVALUES ('Testkunde', 'Viborg');\nSELECT name, city FROM customers\nWHERE name = 'Testkunde';\nROLLBACK;", [new("EF Core: Valg af teststrategi", "https://learn.microsoft.com/en-us/ef/core/testing/choosing-a-testing-strategy"), new("PostgreSQL 16: Constraints", "https://www.postgresql.org/docs/16/ddl-constraints.html")])
    ]);
}

